import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DPaNRfRs.js";var i=JSON.parse(`{"title":"Function: withRunContextTools()","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://sqlrooms.org/api/ai-core/functions/withRunContextTools.html"}]]},"headers":[],"relativePath":"api/ai-core/functions/withRunContextTools.md","filePath":"api/ai-core/functions/withRunContextTools.md"}`),a={name:`api/ai-core/functions/withRunContextTools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /api/ai-core/functions/withRunContextTools.md for this page in Markdown format</div><p><a href="./../">@sqlrooms/ai-core</a> / withRunContextTools</p><h1 id="function-withruncontexttools" tabindex="-1">Function: withRunContextTools() <a class="header-anchor" href="#function-withruncontexttools" aria-label="Permalink to “Function: withRunContextTools()”">​</a></h1><blockquote><p><strong>withRunContextTools</strong>(<code>tools</code>, <code>args</code>): <code>ToolSet</code></p></blockquote><p>Wrap every executable tool in <code>tools</code> so it receives the invoking turn&#39;s execution scope (<code>sessionId</code> plus the mutable <code>AiRunContext</code> accessors) in its AI SDK execution options.</p><p>Use this wherever a toolset is handed to an agent that does not itself own the chat request — most importantly for nested <code>ToolLoopAgent</code> sub-agents, whose tools would otherwise execute with no scope at all and fall back to whatever artifact/map/session is currently visible in the UI.</p><p>Semantics:</p><ul><li>Parent scope wins over inner options when the parent supplies a value, so a nested agent cannot accidentally reassign the owning session. Fields the parent leaves <code>undefined</code> preserve whatever the inner options already had.</li><li><code>getAiRunContext</code> is read at execution time rather than captured, so an in-turn retarget (e.g. <code>set_primary_context_artifact</code>) is visible to later tool calls, including those inside nested agents.</li><li>The inner tool&#39;s own <code>toolCallId</code>, <code>messages</code>, and <code>abortSignal</code> are left intact.</li><li><code>state</code> is optional and only used for <code>setToolCallSession</code> attribution. Omit it when forwarding into nested agents; the chat transport passes it so top-level tool calls stay attributed to their session.</li><li><code>getState</code> lets timeout cleanup read the latest nested-agent progress. It should be supplied by transports that provide <code>state</code>.</li><li>Configured per-tool timeouts preserve upstream cancellation signals and abort the signal forwarded to the wrapped tool when its limit expires.</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>tools</code></td><td><code>ToolSet</code></td></tr><tr><td><code>args</code></td><td><a href="./../type-aliases/AiToolExecutionContext.html"><code>AiToolExecutionContext</code></a> &amp; <code>object</code></td></tr></tbody></table><h2 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h2><p><code>ToolSet</code></p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};